import type { GlobalSetting } from './global-setting-model';
import type { Person } from './person-model';
import type { Workspace } from './workspace-model';

export interface ServiceSettingOverride {
  /**
   * @displayName Service Setting Override ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Service Setting Override Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  serviceSettingOverrideName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Global Setting
   * @validationRule Required for create/update operations
   */
  globalSetting: Pick<GlobalSetting, 'id' | 'settingKey'>;
  /**
   * @displayName Override Value
   * @validationRule Required for create/update operations
   */
  overrideValue: string;
  /**
   * @displayName Service Code
   * @validationRule Required for create/update operations
   */
  serviceCode: string;
  /**
   * @displayName Service Name
   * @validationRule Required for create/update operations
   */
  serviceName: string;
  /**
   * @displayName Updated At
   * @validationRule Required for create/update operations
   */
  updatedAt: string;
  /**
   * @displayName Updated By
   * @validationRule Required for create/update operations
   */
  updatedBy: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _ServiceSettingOverride = 'ServiceSettingOverride' as const;